window.HVAC_EZ_ROWS=[{"key": "ceilingCool", "value": 1, "label": ["Cấp lạnh từ trần", "Cool ceiling supply"], "condition": ["Gió cấp lạnh hơn phòng.", "Supply cooler than room."]}, {"key": "warmFloorReturn", "value": 1, "label": ["Cấp nóng từ trần, hồi thấp", "Warm ceiling supply, low return"], "condition": ["Miệng hồi dưới vùng hô hấp.", "Return below breathing zone."]}, {"key": "warmHigh", "value": 0.8, "label": ["Cấp nóng từ trần, hồi cao — ΔT ≥ 8°C", "Warm ceiling supply, high return — ΔT ≥ 8°C"], "condition": ["Nhiệt độ cấp cao hơn phòng từ 8°C.", "Supply at least 8°C warmer than room."]}, {"key": "warmLowThrow", "value": 0.8, "label": ["Cấp nóng từ trần, hồi cao — tia gió yếu", "Warm ceiling supply, high return — weak jet"], "condition": ["0 < ΔT < 8°C; tia gió < 0,8 m/s tại vùng cách sàn 1,4 m.", "0 < ΔT < 8°C; jet below 0.8 m/s within 1.4 m of floor."]}, {"key": "warmGoodThrow", "value": 1, "label": ["Cấp nóng từ trần, hồi cao — tia gió tới vùng sử dụng", "Warm ceiling supply, high return — adequate throw"], "condition": ["0 < ΔT < 8°C; tia gió ≥ 0,8 m/s tới vùng cách sàn 1,4 m.", "0 < ΔT < 8°C; jet at least 0.8 m/s reaches within 1.4 m of floor."]}, {"key": "floorCoolMixed", "value": 1, "label": ["Cấp lạnh thấp, hồi cao — hòa trộn", "Low cool supply, high return — mixed"], "condition": ["Vận tốc tia thẳng đứng > 0,25 m/s ở cao độ từ 1,4 m.", "Vertical jet above 0.25 m/s at 1.4 m or higher."]}, {"key": "floorWarmLow", "value": 1, "label": ["Cấp nóng thấp, hồi thấp", "Low warm supply, low return"], "condition": ["Gió cấp nóng hơn phòng.", "Supply warmer than room."]}, {"key": "floorWarmHigh", "value": 0.7, "label": ["Cấp nóng thấp, hồi cao", "Low warm supply, high return"], "condition": ["Gió cấp nóng hơn phòng.", "Supply warmer than room."]}];
(()=>{'use strict';const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),rows=window.HVAC_EZ_ROWS,source='https://www.ashrae.org/File%20Library/Technical%20Resources/Standards%20and%20Guidelines/Standards%20Addenda/62.1-2016/62_1_2016_ah_20190627.pdf',reference='ASHRAE 62.1-2016 · Addendum ah (2019) · Table 6.2.2.2';
const note=L('Bảng tóm tắt một số cấu hình hòa trộn. Đối chiếu phiên bản tiêu chuẩn của dự án; không bao gồm mọi hệ phân tầng hoặc thông gió cá nhân. Tốc độ tia gió tại vùng sử dụng không phải vận tốc mặt miệng gió.','Selected mixed-air configurations only. Check the project’s standard edition; stratified and personalized systems are not fully covered. Jet speed in the occupied zone is not diffuser face velocity.');
window.HVACEzGuide={report(x){const row=rows.find(v=>v.key===x.ezConfig);const matches=row&&Math.abs(row.value-x.ez)<1e-9;return '<section class="ez-selection-note"><h3>'+L('Cơ sở chọn Ez','Ez selection basis')+'</h3><p>'+E(matches?row.label[en?1:0]:L('Tùy chỉnh / chưa xác nhận cấu hình','Custom / configuration not confirmed'))+' · Ez = '+E(x.ez)+'</p>'+(matches?'<p>'+E(row.condition[en?1:0])+'</p><p><a href="'+source+'" target="_blank" rel="noopener noreferrer nofollow">'+reference+' ↗</a></p>':'<p>'+L('Giá trị nhập theo hồ sơ thiết kế; cần xác nhận điều kiện áp dụng.','Entered design value; confirm applicable conditions.')+'</p>')+'<p class="field-help">'+note+'</p></section>';},mount(){const field=document.querySelector('[data-field="ezConfig"]');if(!field)return;const b=document.createElement('button');b.type='button';b.className='ez-guide-button';b.textContent=L('Hướng dẫn chọn Ez','Ez selection guide');field.append(b);b.onclick=()=>{document.getElementById('ez-guide-dialog')?.remove();const d=document.createElement('dialog');d.id='ez-guide-dialog';d.className='project-report-dialog';d.setAttribute('aria-label',L('Hướng dẫn chọn Ez','Ez selection guide'));d.innerHTML='<div class="project-actions"><button type="button" data-ez-close>'+L('Đóng','Close')+'</button></div><h2>'+L('Chọn hiệu quả phân phối khí vùng — Ez','Choose zone air distribution effectiveness — Ez')+'</h2><p class="field-help">'+note+'</p><p><a href="'+source+'" target="_blank" rel="noopener noreferrer nofollow">'+reference+' ↗</a></p><div class="calc-table-scroll"><table class="calc-output-table ez-guide-table"><thead><tr><th>'+L('Bố trí cấp / hồi','Supply / return arrangement')+'</th><th>'+L('Điều kiện áp dụng','Conditions')+'</th><th>Ez</th><th></th></tr></thead><tbody>'+rows.map(v=>'<tr><td>'+E(v.label[en?1:0])+'</td><td>'+E(v.condition[en?1:0])+'</td><td>'+v.value+'</td><td><button type="button" data-ez-apply="'+v.key+'" aria-label="'+E(L('Áp dụng: ','Apply: ')+v.label[en?1:0])+'">'+L('Áp dụng','Apply')+'</button></td></tr>').join('')+'</tbody></table></div><p class="field-help">'+L('Cấp/hồi cao và thấp được phân biệt theo cao độ khoảng 1,4 m so với sàn. ΔT = nhiệt độ gió cấp − nhiệt độ phòng. Chỉ chọn dòng khi tất cả điều kiện phù hợp; cấu hình khác hãy dùng Tùy chỉnh và tra tài liệu đầy đủ.','High and low supply/return are distinguished at approximately 1.4 m above floor level. ΔT = supply temperature − room temperature. Apply only when all conditions match; use Custom and the full reference for other arrangements.')+'</p>';document.body.append(d);d.querySelector('[data-ez-close]').onclick=()=>d.close();d.addEventListener('click',e=>{const k=e.target.closest('[data-ez-apply]')?.dataset.ezApply;if(!k)return;const select=document.getElementById('t-ezConfig');select.value=k;select.dispatchEvent(new Event('change',{bubbles:true}));d.close();});d.showModal();}}};
})();
